import java.io.*;
import java.util.*;

public class Codeforces
{
    public static void main(String[] args) throws Exception
    {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        String[] input = reader.readLine().split(" ");
        int total = Integer.parseInt(input[0]);
        double threshold = Double.parseDouble(input[1]);
        int count;
        for(count=0; count<=total; count++)
        {
            if(calculateProbability(total, count) >= threshold) break;
        }
        System.out.println(count);
        reader.close();
    }

    static int ncr(int n, int r)
    {
        if(r > n) return 0;
        int result=1;
        for(int i=n; i>n-r; i--) result*=i;
        for(int i=2; i<=r; i++) result/=i;
        return result;
    }

    static double calculateProbability(int n, int x)
    {
        int a = ncr(x, 3) * ncr(n - x, 0);
        int b = ncr(x, 2) * ncr(n - x, 1);
        int c = ncr(x, 1) * ncr(n - x, 2);
        return ((3.0/6)*c + a + b) / ncr(n, 3);
    }
}
