#include <iostream>
#include <vector>
using namespace std;

int ncr(int n, int r) {
    if (r > n) return 0;
    int result = 1;
    for (int i = n; i > n - r; i--) result *= i;
    for (int i = 2; i <= r; i++) result /= i;
    return result;
}

double calculateProbability(int n, int x) {
    int a = ncr(x, 3) * ncr(n - x, 0);
    int b = ncr(x, 2) * ncr(n - x, 1);
    int c = ncr(x, 1) * ncr(n - x, 2);
    return ((3.0 / 6) * c + a + b) / ncr(n, 3);
}

int main() {
    int total;
    double threshold;
    cin >> total >> threshold;
    int count;
    for (count = 0; count <= total; count++) {
        if (calculateProbability(total, count) >= threshold) break;
    }
    cout << count << endl;
    return 0;
}

